class Solution:
    def surfaceArea(self, grid):
        n = len(grid)
        dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))
        area = 0
        for i in range(n):
            for j in range(n):
                v = grid[i][j]
                if not v:
                    continue
                area += 2
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    h = grid[ni][nj] if 0 <= ni < n and 0 <= nj < n else 0
                    area += max(v - h, 0)
        return area

