class Solution {
public:
    int surfaceArea(vector<vector<int>>& grid) {
        int n = grid.size(), area = 0;
        int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (!v) continue;
                area += 2;
                for (auto& d : dirs) {
                    int ni = i + d[0], nj = j + d[1];
                    int h = (ni >= 0 && ni < n && nj >= 0 && nj < n) ? grid[ni][nj] : 0;
                    area += max(v - h, 0);
                }
            }
        }
        return area;
    }
};

